usage.code:
// Most labels need no code at all: add a LocalizedText beside the TMP_Text and type the key.

// Reading a string from anywhere, holding no reference:
string title = LocalizationManager.Instance.Get("demo.title");
string coins = LocalizationManager.Instance.Get("hud.score", 7, 10);   // fills {0} and {1}

// A language picker button:
LocalizationManager.Instance.SetLocale("fr");

// Arguments for a label are set ONCE and survive every later language change:
LocalizedText greeting = greetingLabel.GetComponent<LocalizedText>();
greeting.SetArguments(playerName);
